def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    ink = next(v for v in Counter(x for row in grid for x in row) if v != background)
    out = [row[:] for row in grid]

    # Find the smallest rectangular frame made from the non-background color.
    for r1 in range(h):
        for r2 in range(r1 + 2, h):
            for c1 in range(w):
                for c2 in range(c1 + 2, w):
                    if (all(grid[r1][c] == ink for c in range(c1, c2 + 1)) and
                        all(grid[r2][c] == ink for c in range(c1, c2 + 1)) and
                        all(grid[r][c1] == ink and grid[r][c2] == ink
                            for r in range(r1, r2 + 1))):
                        for r in range(r1 + 1, r2):
                            for c in range(c1 + 1, c2):
                                if grid[r][c] == background:
                                    out[r][c] = 4
                        return out
    return out
